func:
// ===== ตั้งค่าพอร์ตเครื่องชั่ง (แก้ตรงนี้แล้ว Deploy) =====
flow.set("sc_dev",  "/dev/ttyUSB0");   // พอร์ตของสาย USB-RS232 (ดูจากปุ่ม ①)
flow.set("sc_baud", 9600);             // Baud rate (หาได้จากปุ่ม ②)
flow.set("sc_fmt",  "cs8 -cstopb -parenb");   // 8N1 (ถ้า 7E1 ใช้ "cs7 -cstopb parenb -parodd")
node.status({ fill: "green", shape: "dot", text: flow.get("sc_dev") + " @ " + flow.get("sc_baud") });
return null;

// ลองอ่านทีละ Baud rate ครั้งละ 2 วินาที (อ่านอย่างเดียว ไม่ส่งอะไรออกไป)
// ระหว่างนี้ให้วางของบนเครื่องชั่ง / กดปุ่ม Print ที่เครื่องชั่ง เผื่อเครื่องชั่งส่งเฉพาะตอนกด
const dev = flow.get("sc_dev") || "/dev/ttyUSB0";
const bauds = [9600, 4800, 2400, 1200, 19200, 38400];
const fmts = [["8N1", "cs8 -cstopb -parenb"], ["7E1", "cs7 -cstopb parenb -parodd"]];
let s = "";
for (const [fn, f] of fmts) for (const b of bauds)
    s += `stty -F ${dev} ${b} ${f} raw -echo 2>&1 && echo "=== ${b} ${fn} ===" && (timeout 2 cat ${dev} | head -c 80 | od -An -c | head -3); `;
msg.payload = "'" + s + "'";
node.status({ fill: "blue", shape: "ring", text: "กำลังลอง " + bauds.length * fmts.length + " แบบ (~25 วิ)…" });
return msg;

// สรุปผล: Baud ที่อ่านแล้วเป็นตัวเลข/ตัวอักษรอ่านออก = ค่าที่ถูก
const out = String(msg.payload || "");
const blocks = out.split("=== ").filter(Boolean).map(b => {
    const nl = b.indexOf("\n"); const head = b.slice(0, nl).replace(" ===", "").trim(); const body = b.slice(nl + 1).trim();
    const txt = body.replace(/\s+/g, " ");
    const readable = (txt.match(/[0-9.+\-gGkKsStT]/g) || []).length;
    return { setting: head, readable, sample: txt.slice(0, 160) || "(ไม่มีข้อมูล)" };
});
blocks.sort((a, b) => b.readable - a.readable);
node.status({ fill: blocks[0] && blocks[0].readable > 10 ? "green" : "yellow", shape: "dot", text: blocks[0] ? "น่าจะเป็น " + blocks[0].setting : "ไม่มีข้อมูล" });
msg.payload = { "น่าจะเป็น": blocks[0] ? blocks[0].setting : null, "ผลทั้งหมด (เรียงจากอ่านออกมากสุด)": blocks, raw_stderr: msg.error || undefined };
return msg;

// เริ่มอ่านต่อเนื่อง ด้วยค่าที่ตั้งไว้ (ไม่ต้องลง package เพิ่ม)
const dev = flow.get("sc_dev"), baud = flow.get("sc_baud"), f = flow.get("sc_fmt");
msg.payload = "'stty -F " + dev + " " + baud + " " + f + " raw -echo && exec cat " + dev + "'";
node.status({ fill: "green", shape: "dot", text: "อ่าน " + dev + " @ " + baud });
return msg;

// รวมข้อมูลเป็นบรรทัด แล้วลองแยกน้ำหนัก (ส่งออกเฉพาะตอนค่าเปลี่ยน หรือทุก 2 วิ)
let buf = (context.get("buf") || "") + (Buffer.isBuffer(msg.payload) ? msg.payload.toString("latin1") : String(msg.payload));
const parts = buf.split(/\r\n|\r|\n/); buf = parts.pop(); if (buf.length > 500) buf = buf.slice(-200);
context.set("buf", buf);
for (const raw of parts) {
    const line = raw.replace(/[\x00-\x1f]/g, "").trim();
    if (!line) continue;
    const m = line.match(/([+-])?\s*(\d+(?:\.\d+)?)\s*(kg|g|lb|ct|pcs)?/i);
    const w = m ? parseFloat((m[1] === "-" ? "-" : "") + m[2]) : null;
    const stable = /\bST\b|^S\s|stable/i.test(line) ? true : /\bUS\b|unstable/i.test(line) ? false : null;
    const last = context.get("last"), now = Date.now();
    node.status({ fill: w === null ? "yellow" : "green", shape: "dot", text: line.slice(0, 40) });
    if (line === last && now - (context.get("t") || 0) < 2000) continue;
    context.set("last", line); context.set("t", now);
    node.send({ payload: { "ข้อความ": line, hex: Buffer.from(raw, "latin1").toString("hex").match(/../g).join(" "),
                           "น้ำหนักที่แยกได้": w, "หน่วย": m && m[3] || "", "นิ่ง": stable, time: new Date().toLocaleTimeString("th-TH") } });
}
return null;
